// JSONRPCMessage represents a JSON-RPC 2.0 message
type JSONRPCMessage struct {
	JSONRPC string          `json:"jsonrpc"`
	ID      interface{}     `json:"id,omitempty"`
	Method  string          `json:"method,omitempty"`
	Params  json.RawMessage `json:"params,omitempty"`
	Result  interface{}     `json:"result,omitempty"`
	Error   *RPCError       `json:"error,omitempty"`
}

// RPCError represents a JSON-RPC error
type RPCError struct {
	Code    int         `json:"code"`
	Message string      `json:"message"`
	Data    interface{} `json:"data,omitempty"`
}

// Position represents a line and character position
type Position struct {
	Line      int `json:"line"`
	Character int `json:"character"`
}

// Range represents a start and end position
type Range struct {
	Start Position `json:"start"`
	End   Position `json:"end"`
}

// Location represents a location in a file
type Location struct {
	URI   string `json:"uri"`
	Range Range  `json:"range"`
}

// Diagnostic represents a diagnostic message
type Diagnostic struct {
	Range              Range       `json:"range"`
	Severity           int         `json:"severity"` // 1=error, 2=warning, 3=info, 4=hint
	Code               string      `json:"code,omitempty"`
	Source             string      `json:"source"`
	Message            string      `json:"message"`
	RelatedInformation []string    `json:"relatedInformation,omitempty"`
}

// InitializeParams represents initialize request parameters
type InitializeParams struct {
	ProcessID             interface{}   `json:"processId"`
	RootPath              string        `json:"rootPath,omitempty"`
	RootURI               string        `json:"rootUri,omitempty"`
