// CompletionParams represents textDocument/completion request
type CompletionParams struct {
	TextDocumentPositionParams
	Context CompletionContext `json:"context,omitempty"`
}

// TextDocumentPositionParams represents a text document position
type TextDocumentPositionParams struct {
	TextDocument TextDocumentIdentifier `json:"textDocument"`
	Position     Position               `json:"position"`
}

// TextDocumentIdentifier represents a text document identifier
type TextDocumentIdentifier struct {
	URI string `json:"uri"`
}

// CompletionContext represents completion context
type CompletionContext struct {
	TriggerKind      int    `json:"triggerKind"`      // 1=invoked, 2=triggerCharacter, 3=triggerForIncompleteCompletions
	TriggerCharacter string `json:"triggerCharacter,omitempty"`
}

// CompletionItem represents a completion item
type CompletionItem struct {
	Label            string `json:"label"`
	Kind             int    `json:"kind"`             // 1=text, 2=method, 3=function, 4=constructor, 5=field, 6=variable, 7=class, 8=interface, 9=module, 10=property, 11=unit, 12=value, 13=enum, 14=keyword, 15=snippet, 16=color, 17=file, 18=reference, 19=folder, 20=enumerator, 21=constant, 22=struct, 23=event, 24=operator, 25=typeParameter
	Detail           string `json:"detail,omitempty"`
	Documentation    string `json:"documentation,omitempty"`
	SortText         string `json:"sortText,omitempty"`
	FilterText       string `json:"filterText,omitempty"`
	InsertText       string `json:"insertText,omitempty"`
	InsertTextFormat int    `json:"insertTextFormat,omitempty"` // 1=plaintext, 2=snippet
	TextEdit         *TextEdit `json:"textEdit,omitempty"`
	AdditionalTextEdits []TextEdit `json:"additionalTextEdits,omitempty"`
	CommitCharacters []string `json:"commitCharacters,omitempty"`
	Command          *Command `json:"command,omitempty"`
