}

// HoverParams represents textDocument/hover request
type HoverParams struct {
	TextDocumentPositionParams
}

// Hover represents a hover result
type Hover struct {
	Contents string `json:"contents"`
	Range    *Range `json:"range,omitempty"`
}

// FormattingOptions represents formatting options
type FormattingOptions struct {
	TabSize      int  `json:"tabSize"`
	InsertSpaces bool `json:"insertSpaces"`
}

// DocumentFormattingParams represents textDocument/formatting request
type DocumentFormattingParams struct {
	TextDocument TextDocumentIdentifier `json:"textDocument"`
	Options      FormattingOptions      `json:"options"`
}

// ============================================================================
// LSP Server Implementation
// ============================================================================

// OpenFile represents an open file in the editor
type OpenFile struct {
	URI     string
	Content string
	Version int
}

// LSPServer implements the Language Server Protocol
type LSPServer struct {
	reader    io.Reader
	writer    io.Writer
	files     map[string]*OpenFile
	filesMu   sync.RWMutex
	nextID    int
	nextIDMu  sync.Mutex
	shutdown  bool
}

// NewLSPServer creates a new LSP server
func NewLSPServer(reader io.Reader, writer io.Writer) *LSPServer {
	return &LSPServer{
		reader:  reader,
		writer:  writer,
		files:   make(map[string]*OpenFile),
		nextID:  1,
		shutdown: false,
	}
}

// Run starts the LSP server
func (s *LSPServer) Run() error {
	scanner := bufio.NewScanner(s.reader)

	for scanner.Scan() {
		line := scanner.Text()

		// Parse Content-Length header
		if len(line) == 0 {
			// Empty line indicates end of headers
			if !scanner.Scan() {
				break
			}

			messageBytes := []byte(scanner.Text())
			var msg JSONRPCMessage

			if err := json.Unmarshal(messageBytes, &msg); err != nil {
				log.Printf("Failed to unmarshal message: %v\n", err)
				continue
			}

			// Handle message
			s.handleMessage(&msg)

			if s.shutdown {
				break
			}
		}
	}

	return scanner.Err()
}

// handleMessage handles an incoming JSON-RPC message
func (s *LSPServer) handleMessage(msg *JSONRPCMessage) {
	switch msg.Method {
	case "initialize":
		s.handleInitialize(msg)
	case "initialized":
		// Acknowledgment - no response needed
	case "shutdown":
		s.handleShutdown(msg)
	case "exit":
		s.shutdown = true
	case "textDocument/didOpen":
		s.handleDidOpen(msg)
	case "textDocument/didChange":
		s.handleDidChange(msg)
	case "textDocument/didClose":
		s.handleDidClose(msg)
	case "textDocument/completion":
		s.handleCompletion(msg)
	case "textDocument/hover":
		s.handleHover(msg)
	case "textDocument/formatting":
		s.handleFormatting(msg)
	case "textDocument/definition":
		s.handleDefinition(msg)
	default:
		// Unknown method - respond with error
		s.sendError(msg.ID, -32601, "Method not found")
	}
}

// handleInitialize handles the initialize request
func (s *LSPServer) handleInitialize(msg *JSONRPCMessage) {
	var params InitializeParams
	if err := json.Unmarshal(msg.Params, &params); err != nil {
		s.sendError(msg.ID, -32700, "Parse error")
		return
	}

	result := InitializeResult{
		Capabilities: ServerCapabilities{
			TextDocumentSync:           1, // Full document sync
			CompletionProvider:         true,
			HoverProvider:              true,
			DefinitionProvider:         true,
			ReferencesProvider:         true,
			DocumentFormattingProvider: true,
			DocumentRangeFormattingProvider: true,
			RenameProvider:             true,
			DiagnosticProvider:         true,
		},
		ServerInfo: ServerInfo{
			Name:    "Polyglot LSP",
			Version: "1.0.0",
		},
	}

	s.sendResponse(msg.ID, result)
}

// handleShutdown handles the shutdown request
func (s *LSPServer) handleShutdown(msg *JSONRPCMessage) {
	s.sendResponse(msg.ID, nil)
	s.shutdown = true
}

// handleDidOpen handles textDocument/didOpen notification
func (s *LSPServer) handleDidOpen(msg *JSONRPCMessage) {
	var params DidOpenParams
	if err := json.Unmarshal(msg.Params, &params); err != nil {
		s.sendError(msg.ID, -32700, "Parse error")
		return
	}

	s.filesMu.Lock()
	s.files[params.TextDocument.URI] = &OpenFile{
		URI:     params.TextDocument.URI,
		Content: params.TextDocument.Text,
		Version: params.TextDocument.Version,
	}
	s.filesMu.Unlock()

	// Publish diagnostics
	s.publishDiagnostics(params.TextDocument.URI, params.TextDocument.Text)
}

// handleDidChange handles textDocument/didChange notification
func (s *LSPServer) handleDidChange(msg *JSONRPCMessage) {
	var params DidChangeParams
	if err := json.Unmarshal(msg.Params, &params); err != nil {
		s.sendError(msg.ID, -32700, "Parse error")
		return
	}

	s.filesMu.Lock()
	if file, ok := s.files[params.TextDocument.URI]; ok {
		// Apply changes
		for _, change := range params.ContentChanges {
			if change.Range == nil {
				// Full document change
				file.Content = change.Text
			} else {
				// Incremental change
				file.Content = applyChange(file.Content, change)
			}
		}
		file.Version = params.TextDocument.Version
	}
	s.filesMu.Unlock()

	// Publish diagnostics
	s.publishDiagnostics(params.TextDocument.URI, params.ContentChanges[0].Text)
}

// handleDidClose handles textDocument/didClose notification
func (s *LSPServer) handleDidClose(msg *JSONRPCMessage) {
	var params struct {
		TextDocument TextDocumentIdentifier `json:"textDocument"`
	}
	if err := json.Unmarshal(msg.Params, &params); err != nil {
		s.sendError(msg.ID, -32700, "Parse error")
		return
	}

	s.filesMu.Lock()
	delete(s.files, params.TextDocument.URI)
	s.filesMu.Unlock()
}

// handleCompletion handles textDocument/completion request
func (s *LSPServer) handleCompletion(msg *JSONRPCMessage) {
	var params CompletionParams
	if err := json.Unmarshal(msg.Params, &params); err != nil {
		s.sendError(msg.ID, -32700, "Parse error")
		return
	}

	s.filesMu.RLock()
	file, ok := s.files[params.TextDocument.URI]
	s.filesMu.RUnlock()

	if !ok {
		s.sendResponse(msg.ID, []CompletionItem{})
		return
	}

	completions := s.provideCompletions(file.Content, params.Position)
	s.sendResponse(msg.ID, completions)
}

// handleHover handles textDocument/hover request
func (s *LSPServer) handleHover(msg *JSONRPCMessage) {
	var params HoverParams
	if err := json.Unmarshal(msg.Params, &params); err != nil {
		s.sendError(msg.ID, -32700, "Parse error")
		return
	}

	s.filesMu.RLock()
	file, ok := s.files[params.TextDocument.URI]
	s.filesMu.RUnlock()

	if !ok {
		s.sendResponse(msg.ID, nil)
		return
	}

	hover := s.provideHover(file.Content, params.Position)
	s.sendResponse(msg.ID, hover)
}

// handleFormatting handles textDocument/formatting request
func (s *LSPServer) handleFormatting(msg *JSONRPCMessage) {
	var params DocumentFormattingParams
	if err := json.Unmarshal(msg.Params, &params); err != nil {
		s.sendError(msg.ID, -32700, "Parse error")
		return
	}

	s.filesMu.RLock()
	file, ok := s.files[params.TextDocument.URI]
	s.filesMu.RUnlock()

	if !ok {
		s.sendResponse(msg.ID, []TextEdit{})
		return
	}

	edits := s.provideFormatting(file.Content, params.Options)
	s.sendResponse(msg.ID, edits)
}

// handleDefinition handles textDocument/definition request
func (s *LSPServer) handleDefinition(msg *JSONRPCMessage) {
	var params HoverParams
	if err := json.Unmarshal(msg.Params, &params); err != nil {
		s.sendError(msg.ID, -32700, "Parse error")
		return
	}

	s.filesMu.RLock()
	file, ok := s.files[params.TextDocument.URI]
	s.filesMu.RUnlock()

	if !ok {
		s.sendResponse(msg.ID, nil)
		return
	}

	location := s.provideDefinition(file.Content, params.Position)
	s.sendResponse(msg.ID, location)
}

// ============================================================================
// Feature Providers
// ============================================================================

// publishDiagnostics publishes diagnostic messages
func (s *LSPServer) publishDiagnostics(uri string, content string) {
	diagnostics := s.provideDiagnostics(content)

	notification := JSONRPCMessage{
		JSONRPC: "2.0",
		Method:  "textDocument/publishDiagnostics",
		Params:  json.RawMessage(mustMarshal(map[string]interface{}{
			"uri":         uri,
			"diagnostics": diagnostics,
		})),
	}

	s.sendMessage(&notification)
}

// provideDiagnostics provides diagnostic messages
func (s *LSPServer) provideDiagnostics(content string) []Diagnostic {
	var diagnostics []Diagnostic

	// Check for common errors
	lines := splitLines(content)
	for i, line := range lines {
		// Unmatched braces/parentheses
		if countChar(line, '{') != countChar(line, '}') {
			diagnostics = append(diagnostics, Diagnostic{
				Range: Range{
					Start: Position{Line: i, Character: 0},
					End:   Position{Line: i, Character: len(line)},
				},
				Severity: 1, // Error
				Source:   "polyglot-lsp",
				Message:  "Unmatched braces",
			})
		}

		// Type annotation without value
		if matchesPattern(line, "let\\s+\\w+\\s*:\\s*\\w+\\s*$") {
			diagnostics = append(diagnostics, Diagnostic{
				Range: Range{
					Start: Position{Line: i, Character: 0},
					End:   Position{Line: i, Character: len(line)},
				},
				Severity: 1, // Error
				Source:   "polyglot-lsp",
				Message:  "Variable declared but not initialized",
			})
		}
	}

	return diagnostics
}

// provideCompletions provides completion items
func (s *LSPServer) provideCompletions(content string, pos Position) []CompletionItem {
	items := []CompletionItem{
		// Keywords
		{Label: "let", Kind: 14, Detail: "Variable declaration"},
		{Label: "function", Kind: 14, Detail: "Function definition"},
		{Label: "if", Kind: 14, Detail: "Conditional statement"},
		{Label: "then", Kind: 14, Detail: "Then branch"},
		{Label: "else", Kind: 14, Detail: "Else branch"},
		{Label: "end", Kind: 14, Detail: "End block"},
		{Label: "match", Kind: 14, Detail: "Pattern matching"},
		{Label: "case", Kind: 14, Detail: "Case branch"},
		{Label: "for", Kind: 14, Detail: "Loop statement"},
		{Label: "while", Kind: 14, Detail: "While loop"},
		{Label: "return", Kind: 14, Detail: "Return statement"},

		// Built-in functions
		{Label: "println", Kind: 3, Detail: "Print with newline", InsertText: "println(${1:})"},
		{Label: "print", Kind: 3, Detail: "Print without newline", InsertText: "print(${1:})"},
		{Label: "array_map", Kind: 3, Detail: "Map over array", InsertText: "array_map(${1:arr}, ${2:fn})"},
		{Label: "array_filter", Kind: 3, Detail: "Filter array", InsertText: "array_filter(${1:arr}, ${2:fn})"},
		{Label: "array_fold", Kind: 3, Detail: "Fold/reduce array", InsertText: "array_fold(${1:arr}, ${2:init}, ${3:fn})"},

		// Types
		{Label: "Int", Kind: 5, Detail: "Integer type"},
		{Label: "Float", Kind: 5, Detail: "Floating point type"},
		{Label: "String", Kind: 5, Detail: "String type"},
		{Label: "Bool", Kind: 5, Detail: "Boolean type"},
		{Label: "Array", Kind: 5, Detail: "Array type"},
		{Label: "Result", Kind: 5, Detail: "Result type"},
		{Label: "Option", Kind: 5, Detail: "Optional type"},
	}

	return items
}

// provideHover provides hover information
func (s *LSPServer) provideHover(content string, pos Position) *Hover {
	lines := splitLines(content)
	if pos.Line >= len(lines) {
		return nil
	}

	line := lines[pos.Line]
	if pos.Character > len(line) {
		return nil
	}

	// Find word at position
	word := extractWord(line, pos.Character)
	if word == "" {
		return nil
	}

	// Provide type information
	hover := &Hover{
		Range: &Range{
			Start: Position{Line: pos.Line, Character: pos.Character - len(word)},
			End:   Position{Line: pos.Line, Character: pos.Character},
		},
	}

	// Return type info based on keyword
	switch word {
	case "let":
		hover.Contents = "`let` - Variable declaration"
	case "function":
		hover.Contents = "`function` - Function definition"
	case "println":
		hover.Contents = "`println(value: String) -> Unit`\n\nPrint value with newline"
	case "array_map":
		hover.Contents = "`array_map(arr: Array[T], fn: (T) -> U) -> Array[U]`\n\nMap function over array"
	default:
		hover.Contents = fmt.Sprintf("Symbol: `%s`", word)
	}

	return hover
}

// provideFormatting provides formatting edits
func (s *LSPServer) provideFormatting(content string, opts FormattingOptions) []TextEdit {
	var edits []TextEdit
	formatted := formatCode(content, opts)

	if formatted != content {
		edits = append(edits, TextEdit{
			Range: Range{
				Start: Position{Line: 0, Character: 0},
				End:   Position{Line: 999999, Character: 999999},
			},
			NewText: formatted,
		})
	}

	return edits
}

