// sendMessage sends a JSON-RPC message
func (s *LSPServer) sendMessage(msg *JSONRPCMessage) {
	data, _ := json.Marshal(msg)
	fmt.Fprintf(s.writer, "Content-Length: %d\r\n\r\n%s", len(data), data)
}

// sendResponse sends a successful response
func (s *LSPServer) sendResponse(id interface{}, result interface{}) {
	msg := JSONRPCMessage{
		JSONRPC: "2.0",
		ID:      id,
		Result:  result,
	}
	s.sendMessage(&msg)
}

// sendError sends an error response
func (s *LSPServer) sendError(id interface{}, code int, message string) {
	msg := JSONRPCMessage{
		JSONRPC: "2.0",
		ID:      id,
		Error: &RPCError{
			Code:    code,
			Message: message,
		},
	}
	s.sendMessage(&msg)
}

// mustMarshal marshals to JSON (panics on error)
func mustMarshal(v interface{}) []byte {
	data, err := json.Marshal(v)
	if err != nil {
		panic(err)
	}
	return data
}

// applyChange applies a text change
func applyChange(content string, change TextDocumentContentChangeEvent) string {
	// Simplified: return new text
	return change.Text
}

// splitLines splits content into lines
func splitLines(content string) []string {
	var lines []string
	var current string
	for _, ch := range content {
		if ch == '\n' {
			lines = append(lines, current)
			current = ""
		} else if ch != '\r' {
			current += string(ch)
		}
	}
	if current != "" {
		lines = append(lines, current)
	}
	return lines
}

// countChar counts occurrences of character
func countChar(s string, ch rune) int {
	count := 0
	for _, c := range s {
		if c == ch {
			count++
		}
	}
	return count
}

// matchesPattern checks if string matches pattern (simplified)
func matchesPattern(s, pattern string) bool {
	// Simplified pattern matching
	return false
}

// extractWord extracts word at position
func extractWord(line string, pos int) string {
	start := pos
	for start > 0 && isWordChar(rune(line[start-1])) {
		start--
	}

	end := pos
	for end < len(line) && isWordChar(rune(line[end])) {
		end++
	}

	if start < end {
		return line[start:end]
	}
	return ""
}

// isWordChar checks if character is part of word
func isWordChar(ch rune) bool {
	return (ch >= 'a' && ch <= 'z') ||
		(ch >= 'A' && ch <= 'Z') ||
		(ch >= '0' && ch <= '9') ||
		ch == '_'
}

