package main

import (
	"fmt"
	"regexp"
	"strings"
)

// ============================================================================
// Diagnostics Module
// ============================================================================
// Provides error and warning detection for FreeLang, Go, C, WASM, FV-Julia
// ============================================================================

// DiagnosticCollector collects diagnostics from source code
type DiagnosticCollector struct {
	source string
	lines  []string
}

// NewDiagnosticCollector creates a new diagnostic collector
func NewDiagnosticCollector(source string) *DiagnosticCollector {
	return &DiagnosticCollector{
		source: source,
		lines:  splitLines(source),
	}
}

// Collect returns all diagnostics
func (dc *DiagnosticCollector) Collect() []Diagnostic {
	var diagnostics []Diagnostic

	// Run all diagnostic checks
	diagnostics = append(diagnostics, dc.checkSyntax()...)
	diagnostics = append(diagnostics, dc.checkTypes()...)
	diagnostics = append(diagnostics, dc.checkUnused()...)
	diagnostics = append(diagnostics, dc.checkWarnings()...)

	return diagnostics
}

// ============================================================================
// Syntax Checks
// ============================================================================

// checkSyntax checks for syntax errors
func (dc *DiagnosticCollector) checkSyntax() []Diagnostic {
	var diags []Diagnostic

	for i, line := range dc.lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "//") {
			continue
		}

		// Check unmatched braces
		if !dc.checkBraces(line, i) {
			diags = append(diags, Diagnostic{
				Range: Range{
					Start: Position{Line: i, Character: 0},
					End:   Position{Line: i, Character: len(line)},
				},
				Severity: 1, // Error
				Source:   "polyglot-lsp",
				Message:  "Unmatched braces or parentheses",
				Code:     "E001",
			})
		}

		// Check function definition
		if strings.Contains(trimmed, "function") && !dc.checkFunctionDef(trimmed) {
			diags = append(diags, Diagnostic{
				Range: Range{
					Start: Position{Line: i, Character: 0},
					End:   Position{Line: i, Character: len(line)},
				},
				Severity: 1, // Error
				Source:   "polyglot-lsp",
				Message:  "Invalid function definition",
				Code:     "E002",
			})
		}

		// Check variable declaration
		if strings.HasPrefix(trimmed, "let ") && !dc.checkVariableDecl(trimmed) {
			diags = append(diags, Diagnostic{
				Range: Range{
					Start: Position{Line: i, Character: 0},
					End:   Position{Line: i, Character: len(line)},
				},
				Severity: 1, // Error
				Source:   "polyglot-lsp",
				Message:  "Invalid variable declaration",
				Code:     "E003",
			})
		}

		// Check control flow syntax
		if strings.HasPrefix(trimmed, "if ") && !dc.checkIfStatement(trimmed) {
			diags = append(diags, Diagnostic{
				Range: Range{
					Start: Position{Line: i, Character: 0},
					End:   Position{Line: i, Character: len(line)},
				},
				Severity: 1, // Error
				Source:   "polyglot-lsp",
				Message:  "Invalid if statement",
				Code:     "E004",
			})
		}
	}

	return diags
}

// checkBraces checks if braces and parentheses are balanced
func (dc *DiagnosticCollector) checkBraces(line string, lineNum int) bool {
	braceCount := 0
	parenCount := 0
	bracketCount := 0
	inString := false
	inComment := false

	for i := 0; i < len(line); i++ {
		ch := line[i]

		// Skip strings
		if ch == '"' && (i == 0 || line[i-1] != '\\') {
			inString = !inString
			continue
		}

		if inString {
			continue
		}

		// Skip comments
		if i+1 < len(line) && line[i] == '/' && line[i+1] == '/' {
			break
		}

		switch ch {
		case '{':
			braceCount++
		case '}':
			braceCount--
		case '(':
			parenCount++
		case ')':
			parenCount--
		case '[':
			bracketCount++
		case ']':
			bracketCount--
		}

		// Check for mismatches during parsing
		if braceCount < 0 || parenCount < 0 || bracketCount < 0 {
			return false
		}
	}

	// Allow unmatched at end of line (might be multiline)
	return braceCount >= 0 && parenCount >= 0 && bracketCount >= 0
}

// checkFunctionDef checks if function definition is valid
func (dc *DiagnosticCollector) checkFunctionDef(line string) bool {
	// function name(params): ReturnType = body
	re := regexp.MustCompile(`function\s+\w+\s*\([^)]*\)\s*:\s*\w+\s*=`)
	return re.MatchString(line) || !strings.Contains(line, "function")
}

// checkVariableDecl checks if variable declaration is valid
func (dc *DiagnosticCollector) checkVariableDecl(line string) bool {
	// let name: Type = value
	// or: let name = value
	re := regexp.MustCompile(`let\s+\w+\s*(:?\s*\w+)?\s*=`)
	return re.MatchString(line)
}

// checkIfStatement checks if if statement is valid
func (dc *DiagnosticCollector) checkIfStatement(line string) bool {
	// if condition then ... else ... end
	return strings.Contains(line, "then") || !strings.HasPrefix(strings.TrimSpace(line), "if")
}

// ============================================================================
// Type Checks
// ============================================================================

// checkTypes checks for type-related errors
func (dc *DiagnosticCollector) checkTypes() []Diagnostic {
	var diags []Diagnostic

	for i, line := range dc.lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "//") {
			continue
		}

		// Check type mismatch in assignments
		if strings.Contains(trimmed, ":") && strings.Contains(trimmed, "=") {
			if mismatch, msg := dc.checkTypeMismatch(trimmed); mismatch {
				diags = append(diags, Diagnostic{
					Range: Range{
						Start: Position{Line: i, Character: 0},
						End:   Position{Line: i, Character: len(line)},
					},
					Severity: 1, // Error
					Source:   "polyglot-lsp",
					Message:  msg,
					Code:     "E101",
				})
			}
		}

		// Check function call type errors
		if dc.hasFunctionCall(trimmed) {
			if err := dc.checkFunctionCall(trimmed); err != "" {
				diags = append(diags, Diagnostic{
					Range: Range{
						Start: Position{Line: i, Character: 0},
						End:   Position{Line: i, Character: len(line)},
					},
					Severity: 1, // Error
					Source:   "polyglot-lsp",
					Message:  err,
					Code:     "E102",
				})
			}
		}
	}

	return diags
}

// checkTypeMismatch checks for type mismatches
func (dc *DiagnosticCollector) checkTypeMismatch(line string) (bool, string) {
	// let x: Int = "hello"  --> Type mismatch
	parts := strings.Split(line, "=")
	if len(parts) != 2 {
		return false, ""
	}

	typeDecl := strings.TrimSpace(parts[0])
	value := strings.TrimSpace(parts[1])

	// Extract type
	var declaredType string
	if strings.Contains(typeDecl, ":") {
		typeParts := strings.Split(typeDecl, ":")
		if len(typeParts) > 1 {
			declaredType = strings.TrimSpace(typeParts[1])
		}
	}

	// Infer value type
	inferredType := dc.inferType(value)

	// Check compatibility
	if declaredType != "" && inferredType != "" && !dc.areTypesCompatible(declaredType, inferredType) {
		return true, fmt.Sprintf("Type mismatch: %s cannot be assigned to %s", inferredType, declaredType)
	}

	return false, ""
}

// hasFunctionCall checks if line contains function call
func (dc *DiagnosticCollector) hasFunctionCall(line string) bool {
	return strings.Contains(line, "(") && strings.Contains(line, ")")
}

// checkFunctionCall checks function call validity
func (dc *DiagnosticCollector) checkFunctionCall(line string) string {
	// Simplified: check basic validity
	openCount := strings.Count(line, "(")
	closeCount := strings.Count(line, ")")

	if openCount != closeCount {
		return "Unmatched parentheses in function call"
	}

	return ""
}

// inferType infers the type of a value
func (dc *DiagnosticCollector) inferType(value string) string {
	value = strings.TrimSpace(value)

	// String literal
	if (strings.HasPrefix(value, "\"") && strings.HasSuffix(value, "\"")) ||
		(strings.HasPrefix(value, "'") && strings.HasSuffix(value, "'")) {
		return "String"
	}

	// Boolean
	if value == "true" || value == "false" {
		return "Bool"
	}

	// Numeric
	if isNumeric(value) {
		if strings.Contains(value, ".") {
			return "Float"
		}
		return "Int"
	}

	// Array
	if strings.HasPrefix(value, "[") && strings.HasSuffix(value, "]") {
		return "Array"
	}

	// Function call (assume returns value)
	if strings.Contains(value, "(") {
		return "Unknown"
	}

	// Unknown
	return "Unknown"
}

// areTypesCompatible checks if two types are compatible
func (dc *DiagnosticCollector) areTypesCompatible(t1, t2 string) bool {
	if t1 == t2 {
		return true
	}

	// Type coercion rules
	compatible := map[string][]string{
		"Float": {"Int", "Float"},
		"Int":   {"Int"},
		"Bool":  {"Bool"},
		"String": {"String"},
		"Unknown": {"Unknown", "Int", "Float", "String", "Bool", "Array"},
	}

	if allowed, exists := compatible[t1]; exists {
		for _, t := range allowed {
			if t == t2 {
				return true
			}
		}
	}

	return false
}

// isNumeric checks if value is numeric
func isNumeric(value string) bool {
	value = strings.TrimSpace(value)

	// Handle negative numbers
	if strings.HasPrefix(value, "-") {
		value = value[1:]
	}

	// Try to parse as number
	for i, ch := range value {
		if i == 0 && ch == '.' {
			return false
		}
		if !((ch >= '0' && ch <= '9') || ch == '.') {
			return false
		}
	}

	return len(value) > 0
}

// ============================================================================
// Unused Variable Checks
// ============================================================================

// checkUnused checks for unused variables and functions
func (dc *DiagnosticCollector) checkUnused() []Diagnostic {
	var diags []Diagnostic

	// Collect all definitions
	defs := dc.collectDefinitions()

	// Check usage of each definition
	for name, defLine := range defs {
		if !dc.isUsed(name) && name != "_" {
			diags = append(diags, Diagnostic{
				Range: Range{
					Start: Position{Line: defLine, Character: 0},
					End:   Position{Line: defLine, Character: len(dc.lines[defLine])},
				},
				Severity: 3, // Warning
				Source:   "polyglot-lsp",
				Message:  fmt.Sprintf("Unused variable: %s", name),
				Code:     "W001",
			})
		}
	}

	return diags
}

// collectDefinitions collects all variable and function definitions
func (dc *DiagnosticCollector) collectDefinitions() map[string]int {
	defs := make(map[string]int)

	for i, line := range dc.lines {
		trimmed := strings.TrimSpace(line)

		// Variable definition
		if strings.HasPrefix(trimmed, "let ") {
			parts := strings.Fields(trimmed)
			if len(parts) > 1 {
				name := parts[1]
				// Remove type annotation
				if idx := strings.Index(name, ":"); idx >= 0 {
					name = name[:idx]
				}
				if idx := strings.Index(name, "="); idx >= 0 {
					name = name[:idx]
				}
				defs[name] = i
			}
		}

		// Function definition
		if strings.Contains(trimmed, "function ") {
			re := regexp.MustCompile(`function\s+(\w+)`)
			matches := re.FindStringSubmatch(trimmed)
			if len(matches) > 1 {
				defs[matches[1]] = i
			}
		}
	}

	return defs
}

// isUsed checks if a name is used in the code
func (dc *DiagnosticCollector) isUsed(name string) bool {
	for _, line := range dc.lines {
		// Skip definition lines
		if strings.Contains(line, "let "+name) || strings.Contains(line, "function "+name) {
			continue
		}

		// Check for usage
		if strings.Contains(line, name) {
			return true
		}
	}

	return false
}

// ============================================================================
// Warning Checks
// ============================================================================

// checkWarnings checks for potential issues
func (dc *DiagnosticCollector) checkWarnings() []Diagnostic {
	var diags []Diagnostic

	for i, line := range dc.lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			continue
		}

		// Variable shadowing
		if strings.HasPrefix(trimmed, "let ") && dc.checkShadowing(trimmed, i) {
			diags = append(diags, Diagnostic{
				Range: Range{
					Start: Position{Line: i, Character: 0},
					End:   Position{Line: i, Character: len(line)},
				},
				Severity: 2, // Warning
				Source:   "polyglot-lsp",
				Message:  "Variable shadowing detected",
				Code:     "W002",
			})
		}

		// Missing return type
		if strings.Contains(trimmed, "function") && !strings.Contains(trimmed, ":") {
			diags = append(diags, Diagnostic{
				Range: Range{
					Start: Position{Line: i, Character: 0},
					End:   Position{Line: i, Character: len(line)},
				},
				Severity: 3, // Info
				Source:   "polyglot-lsp",
				Message:  "Function should have return type annotation",
				Code:     "W003",
			})
		}

		// Deeply nested code
		depth := dc.countIndentation(line)
		if depth > 4 {
			diags = append(diags, Diagnostic{
				Range: Range{
					Start: Position{Line: i, Character: 0},
					End:   Position{Line: i, Character: len(line)},
				},
				Severity: 3, // Info
				Source:   "polyglot-lsp",
				Message:  "Deeply nested code - consider refactoring",
				Code:     "W004",
			})
		}
	}

	return diags
}

// checkShadowing checks for variable shadowing
func (dc *DiagnosticCollector) checkShadowing(line string, currentLine int) bool {
	// Extract variable name
	parts := strings.Fields(line)
	if len(parts) < 2 {
		return false
	}

	varName := parts[1]
	if idx := strings.Index(varName, ":"); idx >= 0 {
		varName = varName[:idx]
	}
	if idx := strings.Index(varName, "="); idx >= 0 {
		varName = varName[:idx]
	}

	// Check if variable was defined before
	for i := 0; i < currentLine; i++ {
		if strings.Contains(dc.lines[i], "let "+varName) {
			return true
		}
	}

	return false
}

// countIndentation counts the indentation level
func (dc *DiagnosticCollector) countIndentation(line string) int {
	count := 0
	for _, ch := range line {
		if ch == ' ' {
			count++
		} else if ch == '\t' {
			count += 4
		} else {
			break
		}
	}
	return count / 2 // Assume 2-space indent
}

