// Provides intelligent code completion for FreeLang, Go, C, WASM, FV-Julia
// ============================================================================

// CompletionProvider provides completion items
type CompletionProvider struct {
	context *CompletionContext
}

// CompletionContext contains completion context
type CompletionContext struct {
	Source        string
	Lines         []string
	Position      Position
	LineContent   string
	PrefixStart   int
	CurrentPrefix string
}

// NewCompletionProvider creates a new completion provider
func NewCompletionProvider(source string, pos Position) *CompletionProvider {
	lines := splitLines(source)
	context := &CompletionContext{
		Source:    source,
		Lines:     lines,
		Position:  pos,
	}

	if pos.Line < len(lines) {
		context.LineContent = lines[pos.Line]
		context.PrefixStart = findPrefixStart(context.LineContent, pos.Character)
		context.CurrentPrefix = context.LineContent[context.PrefixStart:pos.Character]
	}

	return &CompletionProvider{context: context}
}

// Provide returns completion items
func (cp *CompletionProvider) Provide() []CompletionItem {
	var items []CompletionItem

	// Determine completion kind based on context
	switch {
	case cp.isAfterDot():
		items = cp.provideMemberCompletion()
	case cp.isAfterType():
		items = cp.provideTypeCompletion()
	case cp.isInFunctionCall():
		items = cp.provideFunctionParameterCompletion()
	case cp.isInString():
		// No completion in strings
		return []CompletionItem{}
	default:
		items = cp.provideGeneralCompletion()
	}

	// Filter items by current prefix
	items = cp.filterItems(items)

	// Sort items by relevance
	items = cp.sortItems(items)

	return items
}

// ============================================================================
// Completion Kinds
// ============================================================================

// provideMemberCompletion provides member access completion
func (cp *CompletionProvider) provideMemberCompletion() []CompletionItem {
	return []CompletionItem{
		{Label: "length", Kind: 5, Detail: "Get length of array or string"},
		{Label: "size", Kind: 5, Detail: "Get size of collection"},
		{Label: "isEmpty", Kind: 5, Detail: "Check if collection is empty"},
		{Label: "head", Kind: 5, Detail: "Get first element"},
		{Label: "tail", Kind: 5, Detail: "Get remaining elements"},
	}
}

// provideTypeCompletion provides type completion
func (cp *CompletionProvider) provideTypeCompletion() []CompletionItem {
	return []CompletionItem{
		{Label: "Int", Kind: 5, Detail: "Integer type"},
		{Label: "Float", Kind: 5, Detail: "Floating point type"},
		{Label: "String", Kind: 5, Detail: "String type"},
		{Label: "Bool", Kind: 5, Detail: "Boolean type"},
		{Label: "Array", Kind: 5, Detail: "Array type", InsertText: "Array[${1:T}]"},
		{Label: "Dictionary", Kind: 5, Detail: "Dictionary type", InsertText: "Dictionary[${1:K}, ${2:V}]"},
		{Label: "Result", Kind: 5, Detail: "Result type", InsertText: "Result[${1:T}, ${2:E}]"},
		{Label: "Option", Kind: 5, Detail: "Optional type", InsertText: "Option[${1:T}]"},
		{Label: "Unit", Kind: 5, Detail: "Unit type (no return value)"},
	}
}

