func (cp *CompletionProvider) provideFunctionParameterCompletion() []CompletionItem {
	// Get local variables and function parameters
	scope := cp.collectScope()

	var items []CompletionItem
	for name, typ := range scope {
		items = append(items, CompletionItem{
			Label:  name,
			Kind:   6, // Variable
			Detail: "Type: " + typ,
