// isAfterDot checks if completion is after a dot (member access)
func (cp *CompletionProvider) isAfterDot() bool {
	if cp.context.PrefixStart == 0 {
		return false
	}
	return cp.context.LineContent[cp.context.PrefixStart-1] == '.'
}

// isAfterType checks if completion is after type annotation
func (cp *CompletionProvider) isAfterType() bool {
	if cp.context.PrefixStart == 0 {
		return false
	}
	return cp.context.LineContent[cp.context.PrefixStart-1] == ':'
}

// isInFunctionCall checks if completion is inside function call
func (cp *CompletionProvider) isInFunctionCall() bool {
	line := cp.context.LineContent[:cp.context.Position.Character]
	openCount := strings.Count(line, "(")
	closeCount := strings.Count(line, ")")
	return openCount > closeCount
}

// isInString checks if position is inside a string
func (cp *CompletionProvider) isInString() bool {
	line := cp.context.LineContent[:cp.context.Position.Character]
	inString := false
	for i := 0; i < len(line); i++ {
		if line[i] == '"' && (i == 0 || line[i-1] != '\\') {
			inString = !inString
		}
	}
	return inString
}

// collectScope collects available symbols in current scope
func (cp *CompletionProvider) collectScope() map[string]string {
	scope := make(map[string]string)

	// Collect all definitions up to current line
	for i := 0; i <= cp.context.Position.Line && i < len(cp.context.Lines); i++ {
		line := cp.context.Lines[i]

		// Variable definitions
		if strings.HasPrefix(strings.TrimSpace(line), "let ") {
			parts := strings.Fields(strings.TrimSpace(line))
			if len(parts) >= 2 {
				name := parts[1]
				// Extract type if present
				typ := "Unknown"
				if idx := strings.Index(name, ":"); idx >= 0 {
					typ = name[idx+1:]
					name = name[:idx]
				}
				scope[name] = typ
			}
		}

		// Function parameters
		if strings.Contains(line, "function ") && strings.Contains(line, "(") {
			// Extract parameters
			startIdx := strings.Index(line, "(")
			endIdx := strings.Index(line, ")")
			if startIdx >= 0 && endIdx > startIdx {
				params := line[startIdx+1 : endIdx]
				for _, param := range strings.Split(params, ",") {
					param = strings.TrimSpace(param)
					parts := strings.Split(param, ":")
					if len(parts) == 2 {
						name := strings.TrimSpace(parts[0])
						typ := strings.TrimSpace(parts[1])
						scope[name] = typ
					}
				}
			}
		}
	}

	return scope
}

// ============================================================================
// Filtering and Sorting
// ============================================================================

// filterItems filters items by prefix
func (cp *CompletionProvider) filterItems(items []CompletionItem) []CompletionItem {
	if cp.context.CurrentPrefix == "" {
		return items
	}

	prefix := strings.ToLower(cp.context.CurrentPrefix)
	var filtered []CompletionItem

	for _, item := range items {
		if strings.HasPrefix(strings.ToLower(item.Label), prefix) {
			filtered = append(filtered, item)
		}
	}

	return filtered
}

// sortItems sorts items by relevance
func (cp *CompletionProvider) sortItems(items []CompletionItem) []CompletionItem {
	// Simple sort: keywords first, then functions, then variables
	var keywords, functions, variables []CompletionItem

	for _, item := range items {
		switch item.Kind {
		case 14: // Keyword
			keywords = append(keywords, item)
		case 3: // Function
			functions = append(functions, item)
		case 6: // Variable
			variables = append(variables, item)
		default:
			functions = append(functions, item)
		}
	}

	// Combine in order
	var sorted []CompletionItem
	sorted = append(sorted, keywords...)
	sorted = append(sorted, functions...)
	sorted = append(sorted, variables...)

	return sorted
}

// ============================================================================
// Helper Functions
// ============================================================================

// findPrefixStart finds the start position of current prefix
func findPrefixStart(line string, character int) int {
	start := character
	for start > 0 && isWordChar(rune(line[start-1])) {
		start--
	}
	return start
}

