	startIdx := strings.Index(line, "(")
	endIdx := strings.Index(line, ")")
	if startIdx < 0 || endIdx < 0 || endIdx <= startIdx {
		return params
	}

	paramStr := line[startIdx+1 : endIdx]
	for _, param := range strings.Split(paramStr, ",") {
