				Type: strings.TrimSpace(parts[1]),
			})
		}
	}

	return params
}

// extractReturnType extracts return type
func (hp *HoverProvider) extractReturnType(line string) string {
	re := regexp.MustCompile(`\):\s*(\w+(?:\[.*?\])?)`)
	matches := re.FindStringSubmatch(line)
	if len(matches) > 1 {
		return matches[1]
	}
	return ""
}

// analyzeComplexity analyzes time complexity
func (hp *HoverProvider) analyzeComplexity(line string) string {
	line = strings.ToLower(line)

	// Simple heuristics
	if strings.Contains(line, "map") || strings.Contains(line, "filter") {
		return "O(n)"
	}
	if strings.Contains(line, "fold") || strings.Contains(line, "reduce") {
		return "O(n)"
	}
	if strings.Contains(line, "sort") {
		return "O(n log n)"
	}
	if strings.Contains(line, "binary") || strings.Contains(line, "search") {
		return "O(log n)"
	}
	if strings.Contains(line, "fib") || strings.Contains(line, "fibonacci") {
		return "O(2^n) - consider memoization"
	}

	return ""
}

