type Command struct {
	Name        string
	Description string
	Action      func(args []string) error
}

// CommandRegistry holds all available commands
var commands = map[string]*Command{
	"install":   {Name: "install", Description: "Install dependencies", Action: cmdInstall},
	"search":    {Name: "search", Description: "Search for packages", Action: cmdSearch},
	"update":    {Name: "update", Description: "Update dependencies", Action: cmdUpdate},
	"remove":    {Name: "remove", Description: "Remove package", Action: cmdRemove},
	"list":      {Name: "list", Description: "List installed packages", Action: cmdList},
	"info":      {Name: "info", Description: "Show package information", Action: cmdInfo},
	"package":   {Name: "package", Description: "Package current project", Action: cmdPackage},
