	flag.Parse()

	if *versionFlag {
		fmt.Printf("%s version %s\n", AppName, Version)
		os.Exit(0)
	}

	if *helpFlag || flag.NArg() == 0 {
		showHelp()
		os.Exit(0)
	}

	args := flag.Args()
	cmdName := args[0]
	cmdArgs := args[1:]

	cmd, exists := commands[cmdName]
	if !exists {
		fmt.Fprintf(os.Stderr, "Error: unknown command '%s'\n", cmdName)
		showHelp()
		os.Exit(1)
	}

	if err := cmd.Action(cmdArgs); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
}

// showHelp displays help message
func showHelp() {
	fmt.Printf(`Polyglot Package Manager v%s

USAGE:
  %s <command> [options] [arguments]

COMMANDS:
`, Version, AppName)

	for _, cmd := range []string{
		"install", "search", "update", "remove", "list", "info",
		"package", "publish", "verify", "audit", "run", "link", "outdated",
	} {
