  %s update

  # Security audit
  %s audit

  # Package current project
  %s package

  # Publish to registry
  %s publish

For more information, visit: https://github.com/polyglot-poc/pkg
`, AppName, AppName, AppName, AppName, AppName, AppName, AppName, AppName)
}

// ============================================================================
// Commands Implementation
// ============================================================================

// cmdInstall installs dependencies
func cmdInstall(args []string) error {
	pm := NewPackageManager(*verboseFlag)

	if len(args) == 0 {
		// Install all from polyglot.toml
		if err := pm.ReadManifest("polyglot.toml"); err != nil {
			return fmt.Errorf("failed to read manifest: %w", err)
		}
		return pm.InstallAll()
	}

	// Install specific package
	pkgName := args[0]
	version := ""
	if len(args) > 1 {
		version = args[1]
	}

	return pm.InstallPackage(pkgName, version)
}

// cmdSearch searches for packages
func cmdSearch(args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("query required")
	}

	query := args[0]
	lang := ""
	if len(args) > 1 && args[1] == "--lang" && len(args) > 2 {
		lang = args[2]
	}

	pm := NewPackageManager(*verboseFlag)
	results, err := pm.Search(query, lang)
	if err != nil {
		return err
	}

	fmt.Printf("Search results for '%s':\n\n", query)
	for _, result := range results {
		fmt.Printf("  %s@%s (%s)\n", result.Name, result.Version, result.Language)
		fmt.Printf("    Description: %s\n", result.Description)
		fmt.Printf("    Downloads: %d | Stars: %d\n", result.Downloads, result.Stars)
		fmt.Printf("\n")
	}

	return nil
}

// cmdUpdate updates dependencies
func cmdUpdate(args []string) error {
	pm := NewPackageManager(*verboseFlag)

	if len(args) == 0 {
		// Update all
		if err := pm.ReadManifest("polyglot.toml"); err != nil {
			return fmt.Errorf("failed to read manifest: %w", err)
		}
		return pm.UpdateAll()
	}

	// Update specific package
	return pm.UpdatePackage(args[0])
}

// cmdRemove removes a package
func cmdRemove(args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("package name required")
	}

	pm := NewPackageManager(*verboseFlag)
	return pm.RemovePackage(args[0])
}

// cmdList lists installed packages
func cmdList(args []string) error {
	pm := NewPackageManager(*verboseFlag)
	packages, err := pm.ListInstalledPackages()
	if err != nil {
		return err
	}

	fmt.Println("Installed packages:\n")
	fmt.Printf("%-30s %-15s %-15s\n", "NAME", "VERSION", "LANGUAGE")
	fmt.Println(strings.Repeat("-", 60))

	for _, pkg := range packages {
		fmt.Printf("%-30s %-15s %-15s\n", pkg.Name, pkg.Version, pkg.Language)
	}

	fmt.Printf("\nTotal: %d packages\n", len(packages))
	return nil
}

// cmdInfo shows package information
func cmdInfo(args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("package name required")
	}

	pm := NewPackageManager(*verboseFlag)
