func cmdPublish(args []string) error {
	pm := NewPackageManager(*verboseFlag)

	if err := pm.ReadManifest("polyglot.toml"); err != nil {
		return fmt.Errorf("failed to read manifest: %w", err)
	}

	fmt.Println("Publishing to registry...")
	if err := pm.PublishPackage(); err != nil {
		return err
	}

	fmt.Println("✓ Package published successfully")
	return nil
}

// cmdVerify verifies package integrity
func cmdVerify(args []string) error {
	pm := NewPackageManager(*verboseFlag)

	if err := pm.ReadManifest("polyglot.toml"); err != nil {
		return fmt.Errorf("failed to read manifest: %w", err)
	}

	fmt.Println("Verifying integrity...")
	if err := pm.VerifyPackages(); err != nil {
		return err
	}

	fmt.Println("✓ All packages verified")
	return nil
}

// cmdAudit performs security audit
func cmdAudit(args []string) error {
	pm := NewPackageManager(*verboseFlag)

	if err := pm.ReadManifest("polyglot.toml"); err != nil {
		return fmt.Errorf("failed to read manifest: %w", err)
	}

	fmt.Println("Running security audit...")
	vulns, err := pm.AuditSecurity()
	if err != nil {
		return err
	}

	if len(vulns) == 0 {
		fmt.Println("✓ No vulnerabilities found")
		return nil
	}

	fmt.Printf("✗ Found %d vulnerability/vulnerabilities:\n\n", len(vulns))
	for _, vuln := range vulns {
		fmt.Printf("  Package: %s\n", vuln.Package)
		fmt.Printf("  ID: %s\n", vuln.ID)
		fmt.Printf("  Severity: %s\n", vuln.Severity)
		fmt.Printf("  Description: %s\n\n", vuln.Description)
	}

	return nil
}

// cmdRun runs package script
func cmdRun(args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("script name required")
	}

	script := args[0]
	pm := NewPackageManager(*verboseFlag)

	if err := pm.ReadManifest("polyglot.toml"); err != nil {
		return fmt.Errorf("failed to read manifest: %w", err)
	}

	return pm.RunScript(script)
}

// cmdLink links local package
func cmdLink(args []string) error {
	path := "."
	if len(args) > 0 {
		path = args[0]
	}

	pm := NewPackageManager(*verboseFlag)
	return pm.LinkPackage(path)
}

// cmdOutdated lists outdated packages
func cmdOutdated(args []string) error {
	pm := NewPackageManager(*verboseFlag)

	if err := pm.ReadManifest("polyglot.toml"); err != nil {
		return fmt.Errorf("failed to read manifest: %w", err)
	}

	packages, err := pm.FindOutdated()
	if err != nil {
		return err
	}

	if len(packages) == 0 {
		fmt.Println("✓ All packages are up to date")
		return nil
	}

	fmt.Printf("Outdated packages (%d):\n\n", len(packages))
	fmt.Printf("%-30s %-15s %-15s\n", "NAME", "CURRENT", "LATEST")
