	for _, pkg := range packages {
		fmt.Printf("%-30s %-15s %-15s\n", pkg.Name, pkg.CurrentVersion, pkg.LatestVersion)
	}

	return nil
}

// ============================================================================
// Main
// ============================================================================

func init() {
	log.SetFlags(0)
}

