package main

import (
	"fmt"
	"io/ioutil"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"
)

// ============================================================================
// Package Manager Core
// ============================================================================

// PackageManager manages packages across languages
type PackageManager struct {
	verbose  bool
	manifest *Manifest
	registry *Registry
	cache    *Cache
}

// Manifest represents polyglot.toml
type Manifest struct {
	Package struct {
		Name        string `toml:"name"`
		Version     string `toml:"version"`
		Description string `toml:"description"`
		Authors     []string `toml:"authors"`
		License     string `toml:"license"`
	} `toml:"package"`

	Dependencies struct {
		FreeLang  map[string]string `toml:"freelang"`
		Go        map[string]string `toml:"go"`
		C         map[string]string `toml:"c"`
		WASM      map[string]string `toml:"wasm"`
		FVJulia   map[string]string `toml:"fv-julia"`
	} `toml:"dependencies"`

	DevDependencies map[string]string `toml:"dev-dependencies"`

	Build struct {
		Go    string `toml:"go"`
		C     string `toml:"c"`
		WASM  string `toml:"wasm"`
		Run   string `toml:"run"`
	} `toml:"build"`

	Scripts map[string]string `toml:"scripts"`
}

// Package represents a package
type Package struct {
	Name        string
	Version     string
	Language    string
	Description string
	License     string
	Homepage    string
	Repository  string
	Author      string
	Downloads   int
	Stars       int
	Dependencies []Dependency
}

// Dependency represents a package dependency
type Dependency struct {
	Name    string
	Version string
	Language string
}

// SearchResult represents search result
