## 패턴 매칭 (FreeLang)

```freejulia
function classify(x: Int): String =
  match x
    case 0 -> "Zero"
    case 1 -> "One"
    case 2 -> "Two"
    case n if n < 0 -> "Negative"
    case n if n > 10 -> "Large"
    case _ -> "Other"
  end
end

function main(): Unit =
  println(classify(0))    # "Zero"
  println(classify(15))   # "Large"
  println(classify(-5))   # "Negative"
end
```

---

## break, continue, return

### Go

```go
package main

import "fmt"

func main() {
    // break: 루프 종료
    for i := 0; i < 10; i++ {
        if i == 5 {
            break
        }
        fmt.Println(i)
    }

    // continue: 다음 반복으로
