### Map 함수

```go
// Go: 배열의 각 원소에 함수 적용
func mapArray(arr []int, f func(int) int) []int {
    result := make([]int, len(arr))
    for i, v := range arr {
        result[i] = f(v)
    }
    return result
}

func main() {
    arr := []int{1, 2, 3, 4, 5}
    double := func(x int) int { return x * 2 }
    result := mapArray(arr, double)  // [2, 4, 6, 8, 10]
}
