## Phase 1: Go 계산기

```go
package main

import (
    "bufio"
    "fmt"
    "math"
    "os"
    "strconv"
    "strings"
)

func add(a, b float64) float64 {
    return a + b
}

func subtract(a, b float64) float64 {
    return a - b
}

func multiply(a, b float64) float64 {
    return a * b
}

func divide(a, b float64) (float64, error) {
    if b == 0 {
        return 0, fmt.Errorf("division by zero")
    }
    return a / b, nil
}

func power(base, exp float64) float64 {
    return math.Pow(base, exp)
}

func factorial(n int) (int, error) {
    if n < 0 {
        return 0, fmt.Errorf("negative number")
    }
    result := 1
    for i := 2; i <= n; i++ {
        result *= i
    }
    return result, nil
}

func main() {
    reader := bufio.NewReader(os.Stdin)
    var history []string

    fmt.Println("계산기 (exit로 종료)")

    for {
        fmt.Print("> ")
        input, _ := reader.ReadString('\n')
        input = strings.TrimSpace(input)

        if input == "exit" {
            break
        }

        if input == "history" {
            for _, h := range history {
                fmt.Println(h)
            }
            continue
        }

        parts := strings.Fields(input)
        if len(parts) < 3 {
            fmt.Println("형식: <숫자> <연산자> <숫자>")
            continue
        }

        a, _ := strconv.ParseFloat(parts[0], 64)
        op := parts[1]
        b, _ := strconv.ParseFloat(parts[2], 64)

        var result float64
        var err error

        switch op {
        case "+":
            result = add(a, b)
        case "-":
            result = subtract(a, b)
        case "*":
            result = multiply(a, b)
        case "/":
            result, err = divide(a, b)
        case "^":
            result = power(a, b)
        default:
            fmt.Println("알 수 없는 연산자")
            continue
        }

        if err != nil {
            fmt.Println("오류:", err)
        } else {
            fmt.Printf("= %.2f\n", result)
            history = append(history, fmt.Sprintf("%s %s %s = %.2f", parts[0], op, parts[2], result))
        }
    }

    fmt.Println("계산기를 종료합니다")
}
```

