// Fibonacci - Rust Implementation
// Phase 2: Recursion, Iteration, Memoization

use std::time::Instant;
use std::collections::HashMap;

fn fib_recursive(n: u32) -> u32 {
    if n <= 1 {
        return n;
    }
    fib_recursive(n - 1) + fib_recursive(n - 2)
}

fn fib_iterative(n: u32) -> u32 {
    if n <= 1 {
        return n;
    }

    let mut a = 0u32;
    let mut b = 1u32;

    for _ in 2..=n {
        let temp = a + b;
        a = b;
        b = temp;
    }

    b
}

fn fib_memoized(n: u32, memo: &mut HashMap<u32, u32>) -> u32 {
    if let Some(&result) = memo.get(&n) {
        return result;
    }

    let result = if n <= 1 {
        n
    } else {
        fib_memoized(n - 1, memo) + fib_memoized(n - 2, memo)
    };

    memo.insert(n, result);
    result
}

fn main() {
    let n = 10;

    // Recursive
    let start = Instant::now();
    let result_recursive = fib_recursive(n);
    let time_recursive = start.elapsed().as_secs_f64() * 1000.0;

    // Iterative
    let start = Instant::now();
    let result_iterative = fib_iterative(n);
    let time_iterative = start.elapsed().as_secs_f64() * 1000.0;

    // Memoized
    let start = Instant::now();
    let mut memo = HashMap::new();
    let result_memoized = fib_memoized(n, &mut memo);
    let time_memoized = start.elapsed().as_secs_f64() * 1000.0;

    println!("fib({}) = {} (recursive: {:.3}ms)", n, result_recursive, time_recursive);
    println!("fib({}) = {} (iterative: {:.3}ms)", n, result_iterative, time_iterative);
    println!("fib({}) = {} (memoized: {:.3}ms)", n, result_memoized, time_memoized);
}

